# ── Descriptors ──────────────────────────────────────────────────────────────

class TypedDescriptor:
    """Descriptor that enforces a type and optional range constraint."""

    def __init__(self, expected_type: type, lo=None, hi=None):
        self.expected_type = expected_type
        self.lo = lo
        self.hi = hi
        self.name: str = ""

    def __set_name__(self, owner_class: type, name: str):
        self.name = name

    def __get__(self, instance: object, owner_class: type = None) -> Any:
        if not instance:
            return self
        try:
            return getattr(instance, "_" + self.name)
        except AttributeError as e:
            raise TypeError(f"{owner_class} does not have attribute {self.name}") from e

    def __set__(self, instance: object, value: Any) -> None:
        """
        If the passed-in value is of the correct type,
        then set it on the instance.
        Otherwise, raise an error with a useful message.
        """

        if not isinstance(value, self.expected_type):  # noqa: E721
            raise TypeError(f"Expected {self.expected_type}, got {value.__class__.__name__}")
        elif self.lo != None and value < self.lo or \
             self.hi != None and value > self.hi:
            raise ValueError(
                f"value must be between {self.lo} and {self.hi}"
                if self.lo != None and self.hi != None
                else "value must be positive"
            )
        setattr(instance, "_" + self.name, value)


class Integer(TypedDescriptor):
    """Integer descriptor. Enforces that value is an integer."""

    def __set__(self, instance: object, value: Any) -> None:
        super().__set__(instance, int(value))  # noqa: F841


class RangeInt(Integer):
    """Integer descriptor that enforces a range constraint."""

    def __init__(self, lo, hi):
        super().__init__()
        self.lo = lo
        self.hi = hi
    
    def __set__(self, instance: object, value: Any) -> None:
        super().__set__(instance, int(value))
        if self.lo != None and self.hi != None\
           and (not (self.lo <= self.value <= self.hi)):
            raise ValueError(
                f"value must be between {self.lo} and {self.hi}"
                if self.lo != None and self.hi != None
                else "value must be positive"
            )


class PositiveRangeInt(RangeInt):
    """Positive integer descriptor that enforces a range constraint."""

    def __init__(self, lo=1):
        super().__init__(lo, sys.maxsize)

